export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  // State and disturbance estimates
  let initialized = false;
  let px = 0, py = 0, pz = 0;
  let vx = 0, vy = 0, vz = 0;
  let dx = 0, dy = 0, dz = 0;
  let uLag = 0.45;
  let gamma = 19.0; // specific thrust gain (K_T / mass)
  let massEst = 0.78;
  let attRefRoll = 0, attRefPitch = 0;
  let attIntRoll = 0, attIntPitch = 0, yawInt = 0;

  // Navigation state
  let gateIdx = -1;
  let phase = 'align';
  let alignedCount = 0;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (!initialized) {
        initialized = true;
        px = p.x; py = p.y; pz = p.z;
        vx = v.x; vy = v.y; vz = v.z;
      }

      // Compute thrust direction from observed attitude
      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const dirX = Math.cos(att.yaw) * bodyX + Math.sin(att.yaw) * bodyZ;
      const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
      const dirZ = -Math.sin(att.yaw) * bodyX + Math.cos(att.yaw) * bodyZ;

      // Specific thrust magnitude
      const fSpec = Math.max(0, gamma * uLag + (py > 0.085 ? dy / Math.max(0.6, dirY) : 0));
      const aModelX = fSpec * dirX - (0.42 / massEst) * vx;
      const aModelY = gamma * uLag * dirY - (0.42 / massEst) * vy - 9.81;
      const aModelZ = fSpec * dirZ - (0.42 / massEst) * vz;

      // Predict and update observers
      const predVx = vx + (aModelX + dx) * dt;
      const predVy = vy + (aModelY + dy) * dt;
      const predVz = vz + (aModelZ + dz) * dt;

      const predPx = px + vx * dt;
      const predPy = py + vy * dt;
      const predPz = pz + vz * dt;

      const errVx = v.x - predVx;
      const errVy = v.y - predVy;
      const errVz = v.z - predVz;

      px = predPx + 0.65 * (p.x - predPx);
      py = predPy + 0.65 * (p.y - predPy);
      pz = predPz + 0.65 * (p.z - predPz);

      vx = predVx + 0.50 * errVx + 5.0 * (p.x - predPx) * dt;
      vy = predVy + 0.50 * errVy + 5.0 * (p.y - predPy) * dt;
      vz = predVz + 0.50 * errVz + 5.0 * (p.z - predPz) * dt;

      if (py > 0.085) {
        dx = clamp(dx + 32.0 * errVx * dt, -18.0, 18.0);
        dy = clamp(dy + 25.0 * errVy * dt, -10.0, 10.0);
        dz = clamp(dz + 32.0 * errVz * dt, -18.0, 18.0);
        // Slowly adapt gamma and massEst from dy
        if (uLag > 0.25 && dirY > 0.7) {
          gamma = clamp(gamma + 0.8 * dy * dt, 14.5, 27.5);
          massEst = clamp(15.0 / gamma, 0.58, 0.98);
          dy *= 0.96;
        }
      } else {
        vy = Math.max(0, v.y);
      }

      // Navigation logic
      let tx = px, ty = 1.05, tz = pz;
      let tvx = 0, tvy = 0, tvz = 0;
      let kpX = 6.5, kdX = 4.2, kpZ = 7.5, kdZ = 4.6, kpY = 7.5, kdY = 4.5;

      if (obs.gateIndex < 3) {
        const g = obs.nextGate.centre;
        if (gateIdx !== obs.gateIndex) {
          gateIdx = obs.gateIndex;
          phase = 'align';
          alignedCount = 0;
        }

        const dzGate = Math.abs(pz - g.z);
        const dyGate = Math.abs(py - g.y);

        if (phase === 'align') {
          // Stage before gate plane
          const stageDist = 0.28;
          tx = g.x - stageDist;
          ty = g.y;
          tz = g.z;

          // Check if well aligned in Z and Y and near staging X
          if (px > g.x - 0.42 && px < g.x - 0.04 &&
              dzGate < 0.017 && Math.abs(vz) < 0.09 &&
              dyGate < 0.065 && Math.abs(vy) < 0.22 &&
              vx > -0.15) {
            alignedCount++;
          } else {
            alignedCount = Math.max(0, alignedCount - 1);
          }
          if (alignedCount >= 5) {
            phase = 'cross';
          }
        }

        if (phase === 'cross') {
          // Predict Z and Y at gate plane crossing
          const remX = Math.max(0, g.x - px);
          const tCross = clamp(remX / Math.max(0.35, vx), 0.02, 0.25);
          const predZCross = Math.abs((pz + vz * tCross) - g.z);
          const predYCross = Math.abs((py + vy * tCross) - g.y);

          // Abort crossing if a gust pushes Z or Y out of safe window and we can still brake before gate.x
          const stopDist = vx > 0 ? (vx * vx) / (2 * 4.8) : 0;
          if (px < g.x - 0.05 && (dzGate > 0.024 || predZCross > 0.026 || dyGate > 0.10 || predYCross > 0.11) && (px + stopDist < g.x - 0.015)) {
            phase = 'align';
            alignedCount = 0;
            tx = g.x - 0.28;
            ty = g.y;
            tz = g.z;
          } else {
            tx = g.x + 0.38;
            ty = g.y;
            tz = g.z;
            tvx = 0.85;
            // High Z stiffness during crossing
            kpZ = 11.0; kdZ = 5.6;
            kpY = 9.0; kdY = 5.0;
          }
        }
      } else {
        // Fly to landing pad and land
        const pad = obs.pad.centre;
        if (gateIdx !== 3) {
          gateIdx = 3;
          phase = 'pad_approach';
        }
        const distPad = Math.hypot(pad.x - px, pad.z - pz);
        const speedHoriz = Math.hypot(vx, vz);
        tx = pad.x;
        tz = pad.z;

        if (phase === 'pad_approach') {
          // Smooth descent slope as we approach the pad
          ty = clamp(0.18 + 0.75 * distPad, 0.18, 1.05);
          if (distPad < 0.11 && speedHoriz < 0.28 && py < 0.28) {
            phase = 'touchdown';
          }
        }
        if (phase === 'touchdown') {
          if (distPad > 0.145) {
            phase = 'pad_approach';
            ty = 0.18;
          } else {
            ty = 0.04;
            tvy = py > 0.11 ? -0.25 : -0.10;
            kpX = 8.0; kdX = 4.8;
            kpZ = 8.0; kdZ = 4.8;
          }
        }
      }

      // Compute desired accelerations with velocity capping for long transits
      const ex = tx - px;
      const ez = tz - pz;
      const ey = ty - py;

      const maxVx = (obs.gateIndex < 3 && phase === 'align' && ex > 0.35) ? 1.65 : 2.2;
      const maxVz = 1.65;
      const desVx = clamp(tvx + (kpX / kdX) * ex, -maxVx, maxVx);
      const desVz = clamp(tvz + (kpZ / kdZ) * ez, -maxVz, maxVz);
      const desVy = clamp(tvy + (kpY / kdY) * ey, -1.4, 1.8);

      const axDes = clamp(kdX * (desVx - vx), -6.5, 6.5);
      const azDes = clamp(kdZ * (desVz - vz), -6.5, 6.5);
      const ayDes = clamp(kdY * (desVy - vy), -5.0, 6.5);

      // Total required thrust acceleration components
      const reqAx = axDes + (0.42 / massEst) * vx - dx;
      const reqAz = azDes + (0.42 / massEst) * vz - dz;
      const reqAy = Math.max(2.5, ayDes + 9.81 + (0.42 / massEst) * vy);

      // Exact nonlinear attitude mapping
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const reqAxBody = cy * reqAx - sy * reqAz;
      const reqAzBody = sy * reqAx + cy * reqAz;

      let maxTilt = 0.56;
      if (obs.gateIndex === 3 && phase === 'touchdown' && py <= 0.105) {
        maxTilt = 0.15; // Ensure landing tilt < 0.18 rad when on/near pad
      }

      const pitchDes = clamp(Math.atan2(reqAxBody, reqAy), -maxTilt, maxTilt);
      const rollDes = clamp(-Math.atan2(reqAzBody * Math.cos(pitchDes), reqAy), -maxTilt, maxTilt);

      // Reference model for attitude integral (avoids integrating step transient)
      attRefPitch += (pitchDes - attRefPitch) * 0.18;
      attRefRoll += (rollDes - attRefRoll) * 0.18;
      if (py > 0.085) {
        attIntPitch = clamp(attIntPitch + (attRefPitch - att.pitch) * dt, -0.25, 0.25);
        attIntRoll = clamp(attIntRoll + (attRefRoll - att.roll) * dt, -0.25, 0.25);
        yawInt = clamp(yawInt + att.yaw * dt, -0.4, 0.4);
      }

      const pitchCmd = clamp(
        pitchDes + 0.55 * (pitchDes - att.pitch) - 0.07 * rates.pitch + 1.6 * attIntPitch,
        -0.6, 0.6
      );
      const rollCmd = clamp(
        rollDes + 0.55 * (rollDes - att.roll) - 0.07 * rates.roll + 1.6 * attIntRoll,
        -0.6, 0.6
      );
      const yawRateCmd = clamp(-4.5 * att.yaw - 0.4 * rates.yaw - 3.5 * yawInt, -2, 2);

      let thrustCmd = (reqAy - dy) / (gamma * Math.max(0.55, dirY));
      if (obs.gateIndex === 3 && phase === 'touchdown' && py <= 0.082 && Math.hypot(vx, vz) < 0.35) {
        // Sit firmly on the pad once touched down
        thrustCmd = Math.min(thrustCmd, 0.12);
      }
      thrustCmd = clamp(thrustCmd, 0, 1);
      uLag += (thrustCmd - uLag) * (1 - Math.exp(-dt / 0.038));

      return { thrust: thrustCmd, roll: rollCmd, pitch: pitchCmd, yawRate: yawRateCmd };
    },
  };
}

