          tx = g.x + 0.35;
          ty = g.y;
          tz = g.z;
          tvx = 0.75;
          // Gentle forward X acceleration avoids motor saturation and roll coupling
          maxAxPos = 2.4;
          kpZ = 12.5; kdZ = 6.0;
          kpY = 9.5; kdY = 5.0;
        }
