        const pad = obs.pad.centre;
        if (gateIdx !== 3) {
          gateIdx = 3;
          phase = 'pad_approach';
        }
        const distPad = Math.hypot(pad.x - px, pad.z - pz);
        const speedHoriz = Math.hypot(vx, vz);
        tx = pad.x;
        tz = pad.z;
        kpX = 8.0; kdX = 4.8;
        kpZ = 8.0; kdZ = 4.8;

        if (distPad < 0.125 && py < 0.22 && speedHoriz < 0.35) {
          phase = 'touchdown';
        } else if (distPad > 0.145) {
          phase = 'pad_approach';
        }

