          ty = clamp(0.09 + 0.78 * Math.max(0, distPad - 0.09), 0.09, 1.05);
          tvy = distPad < 0.45 ? clamp(-0.8 * (py - 0.09), -0.75, 0) : -0.35;
        } else {
          ty = 0.04;
          tvy = py > 0.105 ? -0.32 : -0.12;
        }
      }

      // Compute desired accelerations
      const ex = tx - px;
      const ez = tz - pz;
      const ey = ty - py;

      const maxVx = (obs.gateIndex < 3 && phase === 'align' && ex > 0.30) ? 1.75 : 2.2;
      const maxVz = 1.75;
      const desVx = clamp(tvx + (kpX / kdX) * ex, -maxVx, maxVx);
      const desVz = clamp(tvz + (kpZ / kdZ) * ez, -maxVz, maxVz);
      const desVy = clamp(tvy + (kpY / kdY) * ey, -1.5, 1.8);

