      pz = predPz + 0.60 * (p.z - predPz);

      vx = predVx + 0.38 * errVx + 4.0 * (p.x - predPx) * dt;
      vy = predVy + 0.38 * errVy + 4.0 * (p.y - predPy) * dt;
      vz = predVz + 0.38 * errVz + 4.0 * (p.z - predPz) * dt;

      if (py > 0.085) {
