      }

      // Navigation logic
      let tx = px, ty = 1.05, tz = pz;
      let tvx = 0, tvy = 0, tvz = 0;
      let kpX = 6.5, kdX = 4.2, kpZ = 7.5, kdZ = 4.6, kpY = 7.5, kdY = 4.5;

      if (obs.gateIndex < 3) {
        const g = obs.nextGate.centre;
        if (gateIdx !== obs.gateIndex) {
          gateIdx = obs.gateIndex;
          phase = 'align';
          alignedCount = 0;
        }

        const dzGate = Math.abs(pz - g.z);
        const dyGate = Math.abs(py - g.y);

        if (phase === 'align') {
          const stageDist = 0.28;
          tx = g.x - stageDist;
          ty = g.y;
          tz = g.z;

          if (px > g.x - 0.42 && px < g.x - 0.04 &&
              dzGate < 0.017 && Math.abs(vz) < 0.09 &&
              dyGate < 0.065 && Math.abs(vy) < 0.22 &&
              vx > -0.15) {
            alignedCount++;
