export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  // State and disturbance estimates
  let initialized = false;
  let px = 0, py = 0, pz = 0;
  let vx = 0, vy = 0, vz = 0;
  let dx = 0, dy = 0, dz = 0;
  let uLag = 0.45;
  let gamma = 19.0;
  let massEst = 0.78;
  let attRefRoll = 0, attRefPitch = 0;
  let attIntRoll = 0, attIntPitch = 0, yawInt = 0;

  // Navigation state
  let gateIdx = -1;
  let phase = 'align';
  let alignedCount = 0;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (!initialized) {
        initialized = true;
        px = p.x; py = p.y; pz = p.z;
        vx = v.x; vy = v.y; vz = v.z;
      }

      // Compute thrust direction from observed attitude
      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const dirX = Math.cos(att.yaw) * bodyX + Math.sin(att.yaw) * bodyZ;
      const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
      const dirZ = -Math.sin(att.yaw) * bodyX + Math.cos(att.yaw) * bodyZ;

      // Specific thrust magnitude
      const fSpec = Math.max(0, gamma * uLag + (py > 0.085 ? dy / Math.max(0.6, dirY) : 0));
      const aModelX = fSpec * dirX - (0.42 / massEst) * vx;
      const aModelY = gamma * uLag * dirY - (0.42 / massEst) * vy - 9.81;
      const aModelZ = fSpec * dirZ - (0.42 / massEst) * vz;

      // Predict and update observers
      const predVx = vx + (aModelX + dx) * dt;
      const predVy = vy + (aModelY + dy) * dt;
      const predVz = vz + (aModelZ + dz) * dt;

      const predPx = px + vx * dt;
      const predPy = py + vy * dt;
      const predPz = pz + vz * dt;

      const errVx = v.x - predVx;
      const errVy = v.y - predVy;
      const errVz = v.z - predVz;

      px = predPx + 0.60 * (p.x - predPx);
      py = predPy + 0.60 * (p.y - predPy);
      pz = predPz + 0.60 * (p.z - predPz);

      vx = predVx + 0.40 * errVx + 4.0 * (p.x - predPx) * dt;
      vy = predVy + 0.38 * errVy + 4.0 * (p.y - predPy) * dt;
      vz = predVz + 0.40 * errVz + 4.0 * (p.z - predPz) * dt;

      if (py > 0.085) {
        dx = clamp(dx + 5.8 * errVx, -22.0, 22.0);
        dy = clamp(dy + 4.2 * errVy, -12.0, 12.0);
        dz = clamp(dz + 5.8 * errVz, -22.0, 22.0);
      } else {
        vy = Math.max(0, v.y);
      }

      // Navigation logic
      let tx = px, ty = 1.05, tz = pz;
      let tvx = 0, tvy = 0, tvz = 0;
      let kpX = 6.8, kdX = 4.3, kpZ = 8.2, kdZ = 4.8, kpY = 7.5, kdY = 4.5;
      let maxAxPos = 6.2;

      if (obs.gateIndex < 3) {
        const g = obs.nextGate.centre;
        if (gateIdx !== obs.gateIndex) {
          gateIdx = obs.gateIndex;
          phase = 'align';
          alignedCount = 0;
        }

        const dzGate = Math.abs(pz - g.z);
        const dyGate = Math.abs(py - g.y);

        if (phase === 'align') {
          const stageDist = 0.23;
          tx = g.x - stageDist;
          ty = g.y;
          tz = g.z;

          if (px > g.x - 0.36 && px < g.x - 0.03 &&
              dzGate < 0.016 && Math.abs(vz) < 0.08 &&
              dyGate < 0.065 && Math.abs(vy) < 0.22 &&
              vx > -0.12) {
            alignedCount++;
          } else {
            alignedCount = Math.max(0, alignedCount - 1);
          }
          if (alignedCount >= 4) {
            phase = 'cross';
          }
        }

        if (phase === 'cross') {
          const remX = Math.max(0, g.x - px);
          const tCross = clamp(remX / Math.max(0.35, vx), 0.02, 0.22);
          const predZCross = Math.abs((pz + vz * tCross) - g.z);
          const predYCross = Math.abs((py + vy * tCross) - g.y);

          const stopDist = vx > 0 ? (vx * vx) / (2 * 5.8) : 0;
          if (px < g.x - 0.035 && (dzGate > 0.023 || predZCross > 0.025 || dyGate > 0.10 || predYCross > 0.11) && (px + stopDist < g.x - 0.005)) {
            phase = 'align';
            alignedCount = 0;
            tx = g.x - 0.23;
            ty = g.y;
            tz = g.z;
          } else {
            tx = g.x + 0.36;
            ty = g.y;
            tz = g.z;
            tvx = 0.85;
            maxAxPos = 3.8;
            kpZ = 11.5; kdZ = 5.6;
            kpY = 9.0; kdY = 5.0;
          }
        }
      } else {
        // Fast approach and positive touchdown on landing pad
        const pad = obs.pad.centre;
        if (gateIdx !== 3) {
          gateIdx = 3;
          phase = 'pad_approach';
        }
        const distPad = Math.hypot(pad.x - px, pad.z - pz);
        const speedHoriz = Math.hypot(vx, vz);
        tx = pad.x;
        tz = pad.z;
        kpX = 8.2; kdX = 4.9;
        kpZ = 8.2; kdZ = 4.9;

        if (phase === 'pad_approach') {
          ty = clamp(0.22 + 0.65 * Math.max(0, distPad - 0.08), 0.22, 1.05);
          tvy = py > 0.30 ? -0.25 : 0;
          if (distPad < 0.090 && speedHoriz < 0.24 && py < 0.27 &&
              Math.abs(att.roll) < 0.22 && Math.abs(att.pitch) < 0.22) {
            phase = 'touchdown';
          }
        }
        if (phase === 'touchdown') {
          if (py > 0.080 && (distPad > 0.120 || speedHoriz > 0.38 ||
              Math.abs(att.roll) > 0.27 || Math.abs(att.pitch) > 0.27)) {
            phase = 'pad_approach';
            ty = 0.24;
            tvy = 0.15;
          } else {
            ty = 0.01;
            tvy = py > 0.11 ? -0.32 : -0.18;
          }
        }
      }

      // Compute desired accelerations with velocity capping for long transits
      const ex = tx - px;
      const ez = tz - pz;
      const ey = ty - py;

      const maxVx = (obs.gateIndex < 3 && phase === 'align' && ex > 0.35) ? 1.80 : 2.2;
      const maxVz = 1.80;
      const desVx = clamp(tvx + (kpX / kdX) * ex, -maxVx, maxVx);
      const desVz = clamp(tvz + (kpZ / kdZ) * ez, -maxVz, maxVz);
      const maxDownVy = (obs.gateIndex === 3 && py < 0.25) ? -0.45 : -1.4;
      const desVy = clamp(tvy + (kpY / kdY) * ey, maxDownVy, 1.40);

      const axDes = clamp(kdX * (desVx - vx), -6.5, maxAxPos);
      const azDes = clamp(kdZ * (desVz - vz), -6.5, 6.5);
      const ayDes = clamp(kdY * (desVy - vy), -4.5, 4.2);

      // Total needed thrust acceleration components
      const reqAx = axDes + (0.42 / massEst) * vx - dx;
      const reqAz = azDes + (0.42 / massEst) * vz - dz;
      const reqAy = Math.max(2.5, ayDes + 9.81 + (0.42 / massEst) * vy);

      // Exact nonlinear attitude mapping
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const reqAxBody = cy * reqAx - sy * reqAz;
      const reqAzBody = sy * reqAx + cy * reqAz;

      let maxTilt = 0.55;
      if (obs.gateIndex === 3 && py <= 0.18) {
        maxTilt = 0.26;
      }

      let pitchDes = clamp(Math.atan2(reqAxBody, reqAy), -maxTilt, maxTilt);
      let rollDes = clamp(-Math.atan2(reqAzBody * Math.cos(pitchDes), reqAy), -maxTilt, maxTilt);

      const onPadGround = obs.gateIndex === 3 && phase === 'touchdown' &&
        Math.hypot(obs.pad.centre.x - px, obs.pad.centre.z - pz) < 0.138 && py <= 0.076;

      if (onPadGround) {
        pitchDes = 0;
        rollDes = 0;
      }

      // Reference model for attitude integral
      attRefPitch += (pitchDes - attRefPitch) * 0.18;
      attRefRoll += (rollDes - attRefRoll) * 0.18;
      if (py > 0.085) {
        attIntPitch = clamp(attIntPitch + (attRefPitch - att.pitch) * dt, -0.25, 0.25);
        attIntRoll = clamp(attIntRoll + (attRefRoll - att.roll) * dt, -0.25, 0.25);
        yawInt = clamp(yawInt + att.yaw * dt, -0.4, 0.4);
      }

      const cmdLim = (obs.gateIndex === 3 && py <= 0.14) ? 0.30 : 0.60;
      const pitchCmd = clamp(
        pitchDes + 0.55 * (pitchDes - att.pitch) - 0.07 * rates.pitch + 1.8 * attIntPitch,
        -cmdLim, cmdLim
      );
      const rollCmd = clamp(
        rollDes + 0.55 * (rollDes - att.roll) - 0.07 * rates.roll + 1.8 * attIntRoll,
        -cmdLim, cmdLim
      );
      const yawRateCmd = clamp(-4.5 * att.yaw - 0.4 * rates.yaw - 3.5 * yawInt, -2, 2);

      let thrustCmd = (reqAy - dy) / (gamma * Math.max(0.55, dirY));
      if (onPadGround) {
        thrustCmd = 0.06;
      }
      thrustCmd = clamp(thrustCmd, 0, 0.88);
      uLag += (thrustCmd - uLag) * (1 - Math.exp(-dt / 0.038));

      return { thrust: thrustCmd, roll: rollCmd, pitch: pitchCmd, yawRate: yawRateCmd };
    },
  };
}

