      let tx = px, ty = 1.05, tz = pz;
      let tvx = 0, tvy = 0, tvz = 0;
      let kpX = 7.0, kdX = 4.4, kpZ = 8.5, kdZ = 4.9, kpY = 7.8, kdY = 4.6;
      let maxAxPos = 6.2;

