              dzGate < 0.017 && Math.abs(vz) < 0.09 &&
              dyGate < 0.068 && Math.abs(vy) < 0.22 &&
              vx > -0.15 && !gustEdgeSoon) {
            alignedCount++;
          } else {
            alignedCount = Math.max(0, alignedCount - 1);
          }
          if (alignedCount >= (knownParams ? 3 : 5)) {
            phase = 'cross';
          }
        }

        if (phase === 'cross') {
          const remX = Math.max(0, g.x - px);
          const tCross = clamp(remX / Math.max(0.35, vx), 0.02, 0.25);
          const predZCross = Math.abs((pz + vz * tCross) - g.z);
          const predYCross = Math.abs((py + vy * tCross) - g.y);

          const stopDist = vx > 0 ? (vx * vx) / (2 * 5.2) : 0;
          if (px < g.x - 0.04 && (dzGate > 0.023 || predZCross > 0.025 || dyGate > 0.10 || predYCross > 0.11) && (px + stopDist < g.x - 0.005)) {
            phase = 'align';
            alignedCount = 0;
            tx = g.x - 0.26;
            ty = g.y;
            tz = g.z;
          } else {
            tx = g.x + 0.38;
            ty = g.y;
            tz = g.z;
            tvx = 0.90;
            maxAxPos = 4.2;
            kpZ = 12.0; kdZ = 5.8;
            kpY = 9.0; kdY = 5.0;
          }
        }
      } else {
        // Fast approach and positive touchdown on landing pad
        const pad = obs.pad.centre;
        if (gateIdx !== 3) {
          gateIdx = 3;
          phase = 'pad_approach';
        }
        const distPad = Math.hypot(pad.x - px, pad.z - pz);
        const speedHoriz = Math.hypot(vx, vz);
        tx = pad.x;
        tz = pad.z;
        kpX = 8.5; kdX = 5.0;
        kpZ = 8.5; kdZ = 5.0;

        if (phase === 'pad_approach') {
          ty = clamp(0.18 + 0.65 * Math.max(0, distPad - 0.08), 0.18, 1.05);
          tvy = py > 0.25 ? -0.30 : 0;
          if (distPad < 0.110 && speedHoriz < 0.30 && py < 0.38 &&
              Math.abs(att.roll) < 0.24 && Math.abs(att.pitch) < 0.24) {
            phase = 'touchdown';
          }
        }
        if (phase === 'touchdown') {
          if (py > 0.080 && (distPad > 0.132 || speedHoriz > 0.42 ||
              Math.abs(att.roll) > 0.29 || Math.abs(att.pitch) > 0.29)) {
            phase = 'pad_approach';
            ty = 0.22;
            tvy = 0.10;
          } else {
            ty = 0.01;
            tvy = py > 0.10 ? -0.38 : -0.20;
          }
        }
      }

      // Compute desired accelerations with velocity capping for long transits
      const ex = tx - px;
      const ez = tz - pz;
      const ey = ty - py;

      const maxVx = (obs.gateIndex < 3 && phase === 'align' && ex > 0.35) ? 1.80 : 2.2;
      const maxVz = 1.80;
      const desVx = clamp(tvx + (kpX / kdX) * ex, -maxVx, maxVx);
      const desVz = clamp(tvz + (kpZ / kdZ) * ez, -maxVz, maxVz);
      const maxDownVy = (obs.gateIndex === 3 && py < 0.25) ? -0.45 : -1.5;
      const desVy = clamp(tvy + (kpY / kdY) * ey, maxDownVy, 1.45);

      const axDes = clamp(kdX * (desVx - vx), -6.5, maxAxPos);
      const azDes = clamp(kdZ * (desVz - vz), -6.5, 6.5);
      const ayDes = clamp(kdY * (desVy - vy), -4.5, 4.2);

      // Total needed thrust acceleration components
      const reqAx = axDes + (0.42 / massEst) * vx - dx;
      const reqAz = azDes + (0.42 / massEst) * vz - dz;
      const reqAy = Math.max(2.5, ayDes + 9.81 + (0.42 / massEst) * vy);

      // Exact nonlinear attitude mapping
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const reqAxBody = cy * reqAx - sy * reqAz;
      const reqAzBody = sy * reqAx + cy * reqAz;

      let maxTilt = 0.54;
      if (obs.gateIndex === 3 && py <= 0.16) {
        maxTilt = 0.28;
      }

      let pitchDes = clamp(Math.atan2(reqAxBody, reqAy), -maxTilt, maxTilt);
      let rollDes = clamp(-Math.atan2(reqAzBody * Math.cos(pitchDes), reqAy), -maxTilt, maxTilt);

      const onPadGround = obs.gateIndex === 3 && phase === 'touchdown' &&
        Math.hypot(obs.pad.centre.x - px, obs.pad.centre.z - pz) < 0.138 && py <= 0.076;

      if (onPadGround) {
        pitchDes = 0;
        rollDes = 0;
      }

      // Compute safe max thrust to prevent weak-motor saturation runaway
      let maxThrust = 0.78;
      if (knownParams) {
        const alpha = knownParams.weakness;
        maxThrust = clamp((1.0 - alpha) / (1.0 - 0.25 * alpha) + 0.04, 0.68, 0.85);
      }
      if (Math.max(Math.abs(pitchDes - att.pitch), Math.abs(rollDes - att.roll)) > 0.10) {
        maxThrust = Math.min(maxThrust, 0.68);
      }

      let thrustCmd = (reqAy - dy) / (gamma * Math.max(0.65, dirY));
      if (onPadGround) {
        thrustCmd = 0.06;
      }
      thrustCmd = clamp(thrustCmd, 0, maxThrust);

      attRefPitch += (pitchDes - attRefPitch) * 0.18;
      attRefRoll += (rollDes - attRefRoll) * 0.18;
      if (py > 0.085) {
        attIntPitch = clamp(attIntPitch + (attRefPitch - att.pitch) * dt, -0.25, 0.25);
        attIntRoll = clamp(attIntRoll + (attRefRoll - att.roll) * dt, -0.25, 0.25);
        yawInt = clamp(yawInt + att.yaw * dt, -0.4, 0.4);
      }

      let pitchBias = 0, rollBias = 0, yawBias = 0;
      if (knownParams) {
        const w = knownParams.weakMotor, alpha = knownParams.weakness;
        const inertia = 0.006 * knownParams.mass / 0.6;
        const scale = (4.0 * alpha * thrustCmd) / (1.0 - 0.25 * alpha);
        rollBias = (scale * 0.115 * MOTOR_Z[w]) / (65.0 * inertia) * 0.45;
        pitchBias = -(scale * 0.115 * MOTOR_X[w]) / (65.0 * inertia) * 0.45;
        yawBias = (scale * 0.014 * SPIN[w]) / (8.0 * inertia);
      }

      const cmdLim = (obs.gateIndex === 3 && py <= 0.13) ? 0.30 : 0.60;
      const pitchCmd = clamp(
        pitchDes + pitchBias + 0.55 * (pitchDes - att.pitch) - 0.07 * rates.pitch + 1.5 * attIntPitch,
        -cmdLim, cmdLim
      );
      const rollCmd = clamp(
        rollDes + rollBias + 0.55 * (rollDes - att.roll) - 0.07 * rates.roll + 1.5 * attIntRoll,
        -cmdLim, cmdLim
      );
      const yawRateCmd = clamp(yawBias - 4.5 * att.yaw - 0.4 * rates.yaw - 3.5 * yawInt, -2, 2);

      uLag += (thrustCmd - uLag) * (1 - Math.exp(-dt / (knownParams ? knownParams.lag : 0.038)));

      return { thrust: thrustCmd, roll: rollCmd, pitch: pitchCmd, yawRate: yawRateCmd };
    },
  };
}

